from AlgorithmImports import *


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.lots = {"A": 0, "B": 0}
        self.order_strategies = {}

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close

        if spy_bar is not None and self.spy_sma.IsReady:
            current_spy_sma = self.spy_sma.Current.Value

            if (
                not self.IsWarmingUp
                and all(symbol in data.Bars for symbol in self.symbols)
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.aapl_rsi.IsReady
            ):
                current_spy_close = spy_bar.Close
                current_aapl_rsi = self.aapl_rsi.Current.Value

                spy_sell = (
                    self.lots["A"] > 0
                    and self.previous_spy_close >= self.previous_spy_sma
                    and current_spy_close < current_spy_sma
                )

                if spy_sell:
                    self._sell_lot("A", self.spy, self.lots["A"])

                if self.lots["A"] == 0:
                    spy_buy = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and current_spy_close > current_spy_sma
                    )

                    if spy_buy:
                        quantity = int(
                            (self.Portfolio.TotalPortfolioValue * 0.40)
                            / current_spy_close
                        )
                        if quantity > 0:
                            order = self.MarketOrder(self.spy, quantity)
                            self.order_strategies[order.OrderId] = "A"

                aapl_sell = (
                    self.lots["B"] > 0
                    and current_aapl_rsi > 60
                )

                if aapl_sell:
                    self._sell_lot("B", self.aapl, self.lots["B"])

                if self.lots["B"] == 0:
                    aapl_buy = self.aapl_red_streak >= 1

                    if aapl_buy and self.Portfolio.Cash >= 20000:
                        quantity = int(20000 / aapl_bar.Close)
                        if quantity > 0:
                            order = self.MarketOrder(self.aapl, quantity)
                            self.order_strategies[order.OrderId] = "B"

            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = current_spy_sma

    def _sell_lot(self, strategy, symbol, quantity):
        if quantity > 0:
            order = self.MarketOrder(symbol, -quantity)
            self.order_strategies[order.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            return

        self.lots[strategy] = max(
            0,
            self.lots[strategy] + int(order_event.FillQuantity)
        )

        del self.order_strategies[order_event.OrderId]
